window.OPRAC={"sources":[{"id":"S-BORT","kind":"tekst","title":"Honoré de Balzac, Ojciec Goriot, tłum. Amelia Bortnowska","edition":"Komedya ludzka, t. 3, wyd. S. Lewental, Warszawa 1881; wydanie Wolnych Lektur","url":"https://wolnelektury.pl/katalog/lektura/ojciec-goriot/","rights":"domena publiczna","status":"odczytany w całości","note":"Tekst wydobyty z PDF Wolnych Lektur; strony według tego PDF (s. 2–128)."},{"id":"S-BOY","kind":"tekst","title":"Honoré de Balzac, Ojciec Goriot, tłum. Tadeusz Boy-Żeleński","edition":"Biblioteka Boya, Zakłady Wydawnicze M. Arct, Warszawa 1938; transkrypcja Wikiźródeł","url":"https://pl.wikisource.org/wiki/Ojciec_Goriot_(Balzac,_1938)/Ojciec_Goriot","rights":"domena publiczna","status":"odczytany w całości","note":"Strony druku (s. 17–267) = numer skanu DjVu minus 4; przesunięcie sprawdzono na trzech obrazach skanu."},{"id":"S-BOY-BALZAK","kind":"krytyka","title":"Tadeusz Boy-Żeleński, Balzak, rozdz. 8: „Komedja ludzka” na tle epoki","edition":"Państwowe Wydawnictwo Książek Szkolnych, Lwów 1934; transkrypcja Wikiźródeł","url":"https://pl.wikisource.org/wiki/Balzak/8._%E2%80%9EKomedja_ludzka%E2%80%9C_na_tle_epoki","rights":"domena publiczna","status":"odczytany w całości","note":"Rozdział zajmuje s. 93–111 druku. Strona druku = numer skanu minus 11 (sprawdzono na skanie 110 = s. 99). Zakres „s. 110–115” z zamówienia to numery skanów, czyli s. 99–104 druku."},{"id":"S-HZ2019","kind":"naukowe","title":"Anna Hanotte-Zawiślak, Le retour du « paradoxe du mandarin » dans la construction de l’arriviste littéraire au XIXe siècle","edition":"Cahiers ERTA 18 (2019), s. 9–23","doi":"10.4467/23538953CE.19.010.10695","url":"https://czasopisma.bg.ug.edu.pl/index.php/CE/article/view/3313","rights":"otwarty dostęp; nie redystrybuujemy PDF","status":"odczytany (s. 9–17)","note":"Wykorzystano wywód o Ojcu Goriot (s. 10–17); część o Claudzie Barsacu pominięto."},{"id":"S-HZ2018","kind":"naukowe","title":"Anna Hanotte-Zawiślak, L’arriviste : emblème du déplacement dans le roman réaliste français des années 1830–1895. Esquisse","edition":"Roczniki Humanistyczne 66/5 (2018), s. 103–113","doi":"10.18290/rh.2018.66.5-7","url":"https://ojs.tnkul.pl/index.php/rh/article/view/6758","rights":"otwarty dostęp; nie redystrybuujemy PDF","status":"odczytany w całości","note":""},{"id":"S-VINC","kind":"naukowe","title":"Geneviève Vinciguerra, Trois drames de la paternité frustrée : Goriot, Vautrin, Balzac","edition":"Littératures 17 (1970), s. 3–14","doi":"10.3406/litts.1970.1025","url":"https://www.persee.fr/doc/litts_0563-9751_1970_num_17_2_1025","rights":"Persée","status":"odczytano tylko s. 3","note":"Pełny tekst i PDF chroni zabezpieczenie antybotowe Persée; wykorzystano wyłącznie pierwszą stronę."},{"id":"S-PAISSE","kind":"naukowe","title":"Jean-Marie Paisse, Un portrait du Père Goriot","edition":"Bulletin de l’Association Guillaume Budé 1968, nr 1, s. 125–130","doi":"10.3406/bude.1968.3004","url":"https://www.persee.fr/doc/bude_0004-5527_1968_num_1_1_3004","rights":"Persée","status":"odczytano tylko s. 125","note":"Autor w zamówieniu nie był podany; ustalono go z rekordu Persée."},{"id":"S-RIEGERT","kind":"naukowe","title":"Guy Riegert, Le Père Goriot (1835)","edition":"Hatier 1992, ISBN 9782218947704","status":"nieodczytany","note":"Pliku EPUB nie było na komputerze w chwili wdrożenia. Żadna teza nie powołuje się na tę książkę."},{"id":"S-MDB","kind":"naukowe","title":"Maison de Balzac, notice: Le Père Goriot","url":"https://www.maisondebalzac.paris.fr/vocabulaire/furne/notices/pere_goriot.htm","status":"niedostępny","note":"26.11.2026 serwis Paris Musées wyświetlał komunikat o przerwie technicznej."},{"id":"S-KUR","kind":"naukowe","title":"Jan Kurowicki, Bulgotanie brudów (Jak interpretować „Ojca Goriot” Honoriusza Balzaca?)","edition":"Dydaktyka Literatury 15 (1995)","url":"https://zbc.uz.zgora.pl/dlibra/publication/59084/edition/50799","status":"tylko opis bibliograficzny","note":"Pełnego tekstu nie pobrano."},{"id":"S-KARCZ","kind":"do pozyskania","title":"Zofia Karczewska-Markiewicz, „Ojciec Goriot” Honoriusza Balzaka (Biblioteka Analiz Literackich 26)","status":"nieodczytany"},{"id":"S-BARB","kind":"do pozyskania","title":"Pierre Barbéris, Le Père Goriot de Balzac. Écriture, structures, significations (1972)","status":"nieodczytany"},{"id":"S-BROOKS","kind":"do pozyskania","title":"Peter Brooks (red.), Père Goriot, Norton Critical Edition (1998)","status":"nieodczytany"},{"id":"S-GINS","kind":"do pozyskania","title":"Michal Peled Ginsburg (red.), Approaches to Teaching Balzac’s Old Goriot (2000)","status":"nieodczytany"}],"timeline":{"world":[{"date":"1813","text":"Goriot, wycofany z interesów, zamieszkuje u pani Vauquer.","ref":"P15","source":null},{"date":"1819","text":"Początek akcji w pensjonacie pani Vauquer.","ref":"P14","source":null},{"date":"grudzień","text":"Rastignac otrzymuje listy od matki i siostry z pieniędzmi, o które prosił.","ref":"P19","source":null},{"date":"luty następnego roku","text":"Mija termin wyprowadzki z pensjonatu; w kolejnych dniach Goriot umiera i zostaje pochowany na Père-Lachaise.","ref":"P16","source":null}],"publication":[{"date":"IX 1834 – 26 I 1835","text":"Balzac pisze powieść.","source":{"id":"S-VINC","loc":"s. 3"}},{"date":"IX 1834","text":"Data umieszczona pod tekstem powieści: Saché, wrzesień 1834.","ref":"P17","source":null},{"date":"1881","text":"Przekład Amelii Bortnowskiej w „Komedyi ludzkiej” wydawanej przez S. Lewentala.","source":{"id":"S-BORT","loc":"metryka wydania Wolnych Lektur"}},{"date":"1934","text":"Tadeusz Boy-Żeleński wydaje monografię „Balzak”.","source":{"id":"S-BOY-BALZAK","loc":"karta tytułowa"}},{"date":"1938","text":"Przekład Boya-Żeleńskiego w Bibliotece Boya.","source":{"id":"S-BOY","loc":"karta tytułowa"}}]},"characters":[{"id":"goriot","name":"Ojciec Goriot","role":"Dawny fabrykant makaronu i handlarz mąki, od 1813 roku lokator pani Vauquer; oddał córkom majątek.","refs":["P15","G17","G03"],"themes":["ojcostwo","idealizacja córek","degradacja"]},{"id":"rastignac","name":"Eugeniusz de Rastignac","role":"Student prawa z ubogiej szlachty prowincjonalnej, kuzyn pani de Beauséant.","refs":["G02","G04","G40"],"themes":["inicjacja społeczna","konflikt ambicji i sumienia"]},{"id":"vautrin","name":"Vautrin (Jakub Collin)","role":"Lokator pensjonatu, w rzeczywistości zbiegły galernik zwany Trompe-la-Mort (u Boya: Ołży-Śmierć).","refs":["G06","P03","G30"],"themes":["alternatywny mentor","bunt","diagnoza hipokryzji"]},{"id":"bianchon","name":"Bianchon","role":"Student medycyny (u Boya: Horacy), przyjaciel Rastignaca; pielęgnuje umierającego Goriota.","refs":["P05","G15","G38"],"themes":["etyczna alternatywa"]},{"id":"anastazja","name":"Anastazja de Restaud","role":"Starsza córka Goriota, żona hrabiego de Restaud, kochanka Maksyma de Trailles.","refs":["G03","G20","G21"],"themes":["zależność od kochanka","dług"]},{"id":"delfina","name":"Delfina de Nucingen","role":"Młodsza córka Goriota, żona bankiera Nucingena; kochanka Rastignaca.","refs":["G03","G22","G23"],"themes":["zależność od męża","aspiracje salonowe"]},{"id":"beauseant","name":"Wicehrabina de Beauséant","role":"Kuzynka Rastignaca, dama z przedmieścia Saint-Germain; porzucona przez markiza d’Ajuda-Pinto.","refs":["G04","G05","P13"],"themes":["protekcja","lekcja świata"]},{"id":"wiktoryna","name":"Wiktoryna Taillefer","role":"Córka bankiera, odsunięta przez ojca od majątku; po śmierci brata jego dziedziczka.","refs":["P18","G07","G14"],"themes":["wydziedziczenie","posag"]},{"id":"couture","name":"Pani Couture","role":"Wdowa po komisarzu wojskowym, daleka krewna matki Wiktoryny i jej opiekunka.","refs":["G07"],"themes":["opieka"]},{"id":"vauquer","name":"Pani Vauquer","role":"Właścicielka pensjonatu przy ulicy Neuve-Sainte-Geneviève.","refs":["G01","G18","G35"],"themes":["szacunek zależny od zapłaty"]},{"id":"michonneau","name":"Panna Michonneau","role":"Lokatorka pensjonatu; za nagrodę pomaga policji zdemaskować Vautrina.","refs":["G24","G25"],"themes":["donos"]},{"id":"poiret","name":"Poiret","role":"Lokator pensjonatu, towarzysz panny Michonneau.","refs":["G25"],"themes":["przeciętność"]},{"id":"nucingen","name":"Baron de Nucingen","role":"Bankier, mąż Delfiny; dysponuje jej posagiem.","refs":["G22","G23"],"themes":["finansjera"]},{"id":"restaud","name":"Hrabia de Restaud","role":"Mąż Anastazji.","refs":["G10"],"themes":["arystokracja"]},{"id":"maksym","name":"Maksym de Trailles","role":"Kochanek Anastazji, gracz i dłużnik.","refs":["G20","G21"],"themes":["dług"]},{"id":"taillefer","name":"Taillefer","role":"Bankier, ojciec Wiktoryny i Michała (Fryderyka); syn ginie w pojedynku.","refs":["P18","G14"],"themes":["dziedziczenie"]}],"relations":[{"id":"R01","from":"goriot","to":"anastazja","type":"pokrewieństwo","label":"ojciec; dał posag i spłaca jej długi","refs":["G03","G21"],"rows":[]},{"id":"R02","from":"goriot","to":"delfina","type":"pokrewieństwo","label":"ojciec; dał posag i oddaje ostatnie środki","refs":["G03","P09"],"rows":[]},{"id":"R03","from":"anastazja","to":"maksym","type":"erotyka","label":"kochanka; płaci jego weksle","refs":["G20","G21"],"rows":[]},{"id":"R04","from":"nucingen","to":"delfina","type":"ekonomia","label":"mąż rozporządza jej posagiem i wyznacza pensję","refs":["G22","G23"],"rows":[]},{"id":"R05","from":"restaud","to":"goriot","type":"prestiż","label":"wstydzi się teścia i wyklucza go z domu","refs":["G10","G11"],"rows":[]},{"id":"R06","from":"beauseant","to":"rastignac","type":"mentoring","label":"wprowadza do świata i uczy jego reguł","refs":["G04","G05"],"rows":[]},{"id":"R07","from":"vautrin","to":"rastignac","type":"mentoring","label":"proponuje drogę na skróty: posag Wiktoryny za śmierć jej brata","refs":["G28","G30","P03"],"rows":[]},{"id":"R08","from":"vautrin","to":"taillefer","type":"przymus","label":"organizuje pojedynek, w którym ginie syn Taillefera","refs":["G13","G14"],"rows":[]},{"id":"R09","from":"rastignac","to":"delfina","type":"erotyka","label":"kochanek; przez nią wchodzi do świata","refs":["G32"],"rows":[]},{"id":"R10","from":"delfina","to":"rastignac","type":"prestiż","label":"przez niego zabiega o zaproszenie do pani de Beauséant","refs":[],"rows":[[2,1]]},{"id":"R12","from":"rastignac","to":"beauseant","type":"pokrewieństwo","label":"kuzyn","refs":["G04"],"rows":[]},{"id":"R13","from":"michonneau","to":"vautrin","type":"przymus","label":"usypia go i ujawnia piętno galernika na zlecenie policji","refs":["G24","G25"],"rows":[]},{"id":"R14","from":"couture","to":"wiktoryna","type":"pokrewieństwo","label":"daleka krewna matki, opiekunka","refs":["G07"],"rows":[]},{"id":"R15","from":"taillefer","to":"wiktoryna","type":"ekonomia","label":"odsuwa córkę od majątku na rzecz syna","refs":["P18"],"rows":[]},{"id":"R16","from":"vauquer","to":"goriot","type":"ekonomia","label":"traktuje go według wysokości opłat","refs":["G18","G35"],"rows":[]},{"id":"R17","from":"rastignac","to":"goriot","type":"ekonomia","label":"sąsiad z pensjonatu; razem z Bianchonem płaci za pogrzeb","refs":["G37","G38"],"rows":[]}],"mechanisms":[{"id":"posag","name":"Posag","def":"Majątek wnoszony przez kobietę decyduje o jej wartości na rynku małżeńskim i przechodzi pod kontrolę męża.","areas":[5,12],"refs":["G03","G12","G22","G30"]},{"id":"dlug","name":"Dług","def":"Weksel i pożyczka podtrzymują pozór zamożności, a ich koszt przerzucany jest na bliskich.","areas":[12,13,6],"refs":["G20","G21"]},{"id":"dziedziczenie","name":"Dziedziczenie","def":"Spadek zmienia pozycję osoby z dnia na dzień i staje się celem intrygi.","areas":[7,12],"refs":["P18","G13","G14"]},{"id":"reputacja","name":"Reputacja","def":"Dobre imię jest kapitałem, który trzeba chronić przed skandalem, nawet za cenę długów.","areas":[16,6],"refs":["G21","P04"]},{"id":"salon","name":"Salon","def":"Salon jest miejscem wymiany: tam zapadają decyzje o tym, kto należy do towarzystwa.","areas":[1,2,15],"refs":["G05","P13"]},{"id":"protekcja","name":"Protekcja","def":"Kariera zależy od poparcia wpływowych osób bardziej niż od pracy i zdolności.","areas":[14,1],"refs":["G04","G28","G29"]},{"id":"wykluczenie","name":"Wykluczenie","def":"Kto traci pieniądze lub pochodzenie zdradza się nazwiskiem, ten zostaje odsunięty.","areas":[15,1,16],"refs":["G10","G11","G34","G39"]},{"id":"koszt-kariery","name":"Koszt kariery","def":"Wejście do świata wymaga wydatków, które ponosi rodzina, kochanka albo cudza krzywda.","areas":[12,14,7],"refs":["P10","G26","G27"]}],"axes":[{"id":"goriot","title":"Degradacja Goriota","steps":[{"ref":"P15","text":"Bogaty lokator wprowadza się do pensjonatu."},{"ref":"G17","text":"Zamożność widać w stroju i bieliźnie."},{"ref":"G18","text":"Przeprowadzka na drugie piętro; gospodyni zmienia sposób zwracania się do niego."},{"ref":"G19","text":"Trzecie piętro, rezygnacja z tabaki, fryzjera i pudru."},{"ref":"G34","text":"Pensjonariusze drwią z niego jako z otępiałego starca."},{"ref":"G08","text":"Niszczy ostatnie srebra, by zdobyć pieniądze dla córki."},{"ref":"P09","text":"W agonii rozpoznaje, że miłość córek zależała od pieniędzy."},{"ref":"G39","text":"Na pogrzeb przyjeżdżają puste powozy córek."}]},{"id":"rastignac","title":"Awans Rastignaca","steps":[{"ref":"G04","text":"List ciotki otwiera drogę do kuzynki."},{"ref":"G02","text":"Odkłada naukę, by poznawać Paryż."},{"ref":"G05","text":"Pani de Beauséant wykłada mu reguły powodzenia."},{"ref":"G26","text":"Prosi rodzinę o pieniądze na wejście do świata."},{"ref":"P05","text":"Pyta Bianchona o paradoks mandaryna."},{"ref":"G31","text":"Odrzuca zbrodniczy plan Vautrina."},{"ref":"G32","text":"Wchodzi do świata u boku Delfiny."},{"ref":"G40","text":"Po pogrzebie Goriota rzuca Paryżowi wyzwanie i idzie na obiad do Delfiny."}]},{"id":"vautrin","title":"Demaskacja Vautrina","steps":[{"ref":"P03","text":"Wykłada Rastignacowi swoją filozofię."},{"ref":"G30","text":"Proponuje układ: milion posagu za dwieście tysięcy prowizji."},{"ref":"G13","text":"Zapowiada pojedynek, który otworzy Wiktorynie drogę do spadku."},{"ref":"G24","text":"Panna Michonneau podaje mu środek usypiający."},{"ref":"G25","text":"Na ramieniu ukazuje się piętno galernika."},{"ref":"G06","text":"Przyznaje się do prawdziwego nazwiska."}]},{"id":"bianchon","title":"Model uczciwego działania: Bianchon","steps":[{"ref":"P05","text":"Odmawia „zabicia mandaryna”, czyli korzyści kosztem cudzego życia."},{"ref":"G15","text":"Bada chorego Goriota i sprowadza lekarza ze szpitala."},{"ref":"G16","text":"Czuwa przy chorym na zmianę z Rastignakiem."},{"ref":"G38","text":"Zdobywa tanią trumnę, gdy rodzina nie płaci za pogrzeb."}]}],"theses":[{"id":"T01","mod":"kontekst","typ":"fakt","text":"Akcja zaczyna się w 1819 roku; Goriot mieszka u pani Vauquer od 1813 roku.","refs":["P14","P15"],"status":"tekst","rows":[],"source":null},{"id":"T02","mod":"kontekst","typ":"fakt","text":"Ostatnie wydarzenia rozgrywają się w lutym następnego roku: pani Vauquer wspomina termin wyprowadzki 15 lutego, a mija już osiemnasty dzień miesiąca.","refs":["P16","P19"],"status":"tekst","note":"Rok 1820 wynika z rachuby: akcja zaczyna się w 1819, listy z domu przychodzą w grudniu, a luty jest następny.","rows":[],"source":null},{"id":"T03","mod":"kontekst","typ":"fakt","text":"Powieść powstawała od końca września 1834 do 26 stycznia 1835 roku; tekst zamyka podpis „Saché, wrzesień 1834”.","refs":["P17"],"source":{"id":"S-VINC","loc":"s. 3"},"status":"źródło-fragment","rows":[]},{"id":"T04","mod":"kontekst","typ":"kontekst","text":"Restauracja oznaczała dla młodego pokolenia zamknięcie dróg awansu, jakie dawało Cesarstwo: liczyły się protekcja i urodzenie.","source":{"id":"S-BOY-BALZAK","quote":"Kazano młodzieży być cierpliwą, posłuszną, nabożną. Brak wszelkiego upustu dla energji, trudność wybicia się, — protekcja i urodzenie w miejsce talentów.","loc":"s. 97–98","seg":[[5,202,355]]},"refs":["G28","G29"],"mech":["protekcja"],"status":"źródło","rows":[]},{"id":"T05","mod":"kontekst","typ":"kontekst","text":"Wywód Vautrina o protekcji pokrywa się z historycznym rozpoznaniem Restauracji jako epoki zablokowanej kariery młodych.","refs":["G28","G29","T04"],"chars":["vautrin","rastignac"],"mech":["protekcja"],"status":"autorska","rows":[],"source":null},{"id":"T06","mod":"kontekst","typ":"fakt","text":"Według noty tłumacza w wydaniu z 1938 roku powieść łączy się treścią m.in. ze „Straconymi złudzeniami”, „Blaskami i nędzami życia kurtyzany”, „Ostatnim wcieleniem Vautrina”, „Kobietą porzuconą”, „Gobseckiem” i „Bankiem Nucingena”.","source":{"id":"S-BOY","loc":"nota po tekście powieści, wyd. 1938"},"status":"źródło","rows":[]},{"id":"T07","mod":"kontekst","typ":"kontekst","text":"Boy wskazuje cykl otwierany przez „Ojca Goriot” jako najlepszy punkt wejścia w „Komedię ludzką”; dalsze losy pani de Beauséant zawiera „Kobieta porzucona”.","source":{"id":"S-BOY-BALZAK","loc":"przypis w rozdz. 8, s. 109 druku"},"chars":["beauseant"],"status":"źródło","rows":[]},{"id":"T08","mod":"kontekst","typ":"kontekst","text":"Ojciec Wiktoryny, Taillefer, pojawia się także w noweli „L’Auberge rouge” (1831), gdzie popełnia morderstwo dla pieniędzy; w „Ojcu Goriot” śmierć jego syna zleca Vautrin z tej samej przyczyny.","source":{"id":"S-HZ2019","loc":"s. 16"},"chars":["taillefer","vautrin"],"status":"źródło","rows":[]},{"id":"T09","mod":"kontekst","typ":"kontekst","text":"W innych utworach cyklu Rastignac zostaje ministrem i parem Francji.","source":{"id":"S-HZ2018","loc":"s. 110"},"chars":["rastignac"],"status":"źródło","rows":[]},{"id":"T10","mod":"kontekst","typ":"interpretacja","text":"Pieniądz jest dla Balzaka siłą przenikającą wszystkie sfery życia, a nie abstrakcyjnym „złotem” dawnej literatury.","source":{"id":"S-BOY-BALZAK","quote":"Pieniądz jest dla Balzaka nicią Arjadny, która prowadzi go nieomylnie w labiryncie nowego społeczeństwa","loc":"s. 101","seg":[[9,552,655]]},"mech":["posag","dlug"],"status":"źródło","rows":[]},{"id":"T11","mod":"paryz","typ":"fakt","text":"Narrator nazywa Paryż oceanem, którego głębokości nie da się zbadać.","refs":["P01"],"motif":["Paryż"],"status":"tekst","rows":[],"source":null},{"id":"T12","mod":"paryz","typ":"interpretacja","text":"Dla bohaterów z prowincji Paryż jest jedynym miejscem, w którym można „zrobić karierę”, ale zarazem siłą, która zwykle niszczy przybyszów.","source":{"id":"S-HZ2018","loc":"s. 108–109"},"chars":["rastignac"],"status":"źródło","rows":[]},{"id":"T13","mod":"paryz","typ":"fakt","text":"Piętro w pensjonacie odpowiada wysokości opłaty: Goriot zubożały przenosi się z pierwszego na drugie, a potem na trzecie piętro.","refs":["G18","G19"],"rows":[[8,3]],"chars":["goriot","vauquer"],"status":"tekst","source":null},{"id":"T14","mod":"paryz","typ":"interpretacja","text":"Pionowy układ pensjonatu jest mapą ekonomiczną: wspinanie się po schodach oznacza spadanie w hierarchii.","refs":["G18","G19","T13"],"chars":["goriot"],"mech":["wykluczenie"],"status":"autorska","rows":[],"source":null},{"id":"T15","mod":"paryz","typ":"fakt","text":"Przestrzeń salonów dzieli się na dzielnice: stara arystokracja na przedmieściu Saint-Germain (pani de Beauséant), nowe pieniądze na Chaussée-d’Antin (hrabina de Restaud).","refs":["P13"],"chars":["beauseant","anastazja"],"mech":["salon"],"status":"tekst","rows":[],"source":null},{"id":"T16","mod":"paryz","typ":"fakt","text":"Vautrin oblicza, że życie młodego eleganta w Paryżu kosztuje dwadzieścia pięć tysięcy franków rocznie, a majątek rodziny Rastignaców przynosi około trzech tysięcy.","refs":["P10"],"source":{"id":"S-HZ2018","loc":"s. 109"},"mech":["koszt-kariery"],"status":"źródło","rows":[]},{"id":"T17","mod":"paryz","typ":"fakt","text":"W ujęciu Vautrina Paryż przyjmuje każdego, kto wraca z łowów na miliony, niezależnie od sposobu ich zdobycia.","refs":["P12","P04"],"chars":["vautrin"],"status":"tekst","rows":[],"source":null},{"id":"T18","mod":"paryz","typ":"interpretacja","text":"Finałowy widok z cmentarza Père-Lachaise zamyka przestrzeń powieści: Rastignac patrzy na dzielnicę wielkiego świata między placem Vendôme a Inwalidami, czyli na cel, a nie na pensjonat.","refs":["P11","G40"],"chars":["rastignac"],"status":"autorska","rows":[],"source":null},{"id":"T19","mod":"bohaterowie","typ":"interpretacja","text":"W tym samym miejscu Bortnowska nazywa Goriota „ideałem ojcostwa”, a Boy — „Chrystusem ojcostwa”; obie wersje zachowują porównanie z męką Zbawiciela. Formułę „le Christ de la paternité” przytacza też krytyka francuska.","refs":["P07"],"source":{"id":"S-VINC","loc":"s. 3"},"chars":["goriot"],"motif":["ojcostwo"],"status":"źródło-fragment","rows":[]},{"id":"T20","mod":"bohaterowie","typ":"fakt","text":"Umierający Goriot mówi, że społeczeństwo opiera się na ojcostwie i runie, jeśli dzieci nie będą kochać rodziców.","refs":["P08"],"chars":["goriot"],"motif":["ojcostwo"],"status":"tekst","rows":[],"source":null},{"id":"T21","mod":"bohaterowie","typ":"interpretacja","text":"Rastignac stoi między dwoma wzorami: Vautrinem, symbolem woli mocy, i Goriotem.","source":{"id":"S-VINC","loc":"s. 3"},"chars":["rastignac","vautrin","goriot"],"status":"źródło-fragment","rows":[]},{"id":"T22","mod":"bohaterowie","typ":"interpretacja","text":"Vautrin reprezentuje bunt przeciw porządkowi społecznemu; Poiret i panna Michonneau — szkodliwą przeciętność.","source":{"id":"S-VINC","loc":"s. 3"},"chars":["vautrin","poiret","michonneau"],"status":"źródło-fragment","rows":[]},{"id":"T23","mod":"bohaterowie","typ":"interpretacja","text":"Bianchon to „poważny student”, przedstawiciel arystokracji umysłu; Wiktoryna — łagodność, pobożność i rezygnacja.","source":{"id":"S-VINC","loc":"s. 3"},"chars":["bianchon","wiktoryna"],"status":"źródło-fragment","rows":[]},{"id":"T24","mod":"bohaterowie","typ":"interpretacja","text":"Rastignac przez Delfinę wchodzi w świat wielkiej finansjery, a Anastazja wprowadza powieść w świat lichwiarzy.","source":{"id":"S-VINC","loc":"s. 3"},"refs":["G23","G21"],"chars":["delfina","anastazja","rastignac"],"status":"źródło-fragment","rows":[]},{"id":"T25","mod":"bohaterowie","typ":"interpretacja","text":"Rastignac jest bohaterem „zawieszonym”: oderwał się od swojej klasy, ale nie został jeszcze w pełni przyjęty przez wyższe sfery.","source":{"id":"S-HZ2018","loc":"s. 110"},"chars":["rastignac"],"status":"źródło","rows":[]},{"id":"T26","mod":"bohaterowie","typ":"interpretacja","text":"Na drodze Rastignaca pojawiają się kolejni pomocnicy: pani de Beauséant, Vautrin i Delfina de Nucingen; jego przewagą jest pokrewieństwo z panią de Beauséant.","source":{"id":"S-HZ2018","loc":"s. 106, 111"},"chars":["rastignac","beauseant","vautrin","delfina"],"status":"źródło","rows":[]},{"id":"T27","mod":"bohaterowie","typ":"fakt","text":"Anastazja i Delfina zależą od różnych osób: Anastazja spłaca długi kochanka, Delfina nie może swobodnie rozporządzać posagiem, którym zarządza mąż.","refs":["G20","G21","G22","G23"],"chars":["anastazja","delfina","maksym","nucingen"],"mech":["dlug","posag"],"status":"tekst","rows":[],"source":null},{"id":"T28","mod":"mechanizmy","typ":"interpretacja","text":"Wspomnienie nazwiska Goriota w salonie de Restaud zamyka Rastignacowi drzwi tego domu: pochodzenie z handlu jest w tym świecie piętnem.","refs":["G10","G11"],"source":{"id":"S-HZ2018","loc":"s. 111"},"chars":["rastignac","restaud","goriot"],"mech":["wykluczenie","salon"],"status":"źródło","rows":[]},{"id":"T29","mod":"mechanizmy","typ":"interpretacja","text":"Rastignac nie przyjmuje ofiary z brata Wiktoryny, wybiera bardziej akceptowaną w epoce drogę awansu — związek z żoną bankiera.","source":{"id":"S-HZ2019","loc":"s. 15"},"refs":["G31","G32"],"chars":["rastignac","delfina","wiktoryna"],"mech":["koszt-kariery"],"status":"źródło","rows":[]},{"id":"T30","mod":"mechanizmy","typ":"interpretacja","text":"Miłość w świecie Balzaka często przestaje być celem i staje się środkiem.","source":{"id":"S-BOY-BALZAK","quote":"Miłość aż nazbyt często z celu staje się środkiem.","loc":"s. 107","seg":[[19,564,614]]},"refs":["G05","G32"],"mech":["salon","koszt-kariery"],"status":"źródło","rows":[]},{"id":"T31","mod":"mechanizmy","typ":"fakt","text":"Vautrin traktuje małżeństwo jako transakcję z prowizją: dwieście tysięcy franków za milion posagu.","refs":["G30"],"chars":["vautrin","rastignac","wiktoryna"],"mech":["posag"],"status":"tekst","rows":[],"source":null},{"id":"T32","mod":"mechanizmy","typ":"interpretacja","text":"Bianchon stanowi miarę, wobec której widać koszt wyborów Rastignaca: odrzuca korzyść okupioną cudzym życiem i bezinteresownie opiekuje się Goriotem.","refs":["P05","G15","G38"],"source":{"id":"S-HZ2019","loc":"s. 14"},"chars":["bianchon","rastignac"],"status":"źródło","rows":[]},{"id":"T33","mod":"poetyka","typ":"fakt","text":"Narrator zwraca się wprost do czytelnika i zapewnia, że opowiadany „dramat” nie jest zmyśleniem.","refs":["P02"],"status":"tekst","rows":[],"source":null},{"id":"T34","mod":"poetyka","typ":"interpretacja","text":"Realizm Balzaka nie jest kopiowaniem rzeczywistości: postacie powstają syntetycznie, a obserwacja łączy się z intuicją poety.","source":{"id":"S-BOY-BALZAK","quote":"Bo to nie jest zwykła obserwacja realisty, — to intuicja poety.","loc":"s. 103","seg":[[13,517,580]]},"status":"źródło","rows":[]},{"id":"T35","mod":"poetyka","typ":"interpretacja","text":"Balzac nigdy prawie nie portretował osób z rzeczywistości; tworzył figury syntetyczne.","source":{"id":"S-BOY-BALZAK","quote":"Mimo że nigdy prawie nie portretował z rzeczywistości, ale zawsze tworzył figury swoje syntetycznie","loc":"s. 104","seg":[[15,0,99]]},"status":"źródło","rows":[]},{"id":"T36","mod":"poetyka","typ":"interpretacja","text":"Postać upodabnia się do otoczenia, więc opis miejsca jest zarazem portretem jego mieszkańców.","source":{"id":"S-BOY-BALZAK","quote":"Balzac odgadł prawo mimicry, upodobnianie się żywej osoby do tła.","loc":"s. 104","seg":[[14,593,658]]},"refs":["G01"],"chars":["vauquer"],"status":"źródło","rows":[]},{"id":"T37","mod":"poetyka","typ":"interpretacja","text":"Kilka akapitów o kolejnych latach Goriota w pensjonacie zawiera w zalążku całą jego przemianę; upadek pokazany jest przez zmiany stroju, wyglądu i mieszkania.","refs":["G17","G18","G19"],"source":{"id":"S-PAISSE","loc":"s. 125"},"chars":["goriot"],"status":"źródło-fragment","rows":[]},{"id":"T38","mod":"poetyka","typ":"interpretacja","text":"Wszystkie główne postacie łączą pensjonat Vauquer ze światem zewnętrznym: wielowątkowość ma wspólny punkt w jednym domu.","source":{"id":"S-VINC","loc":"s. 3"},"status":"źródło-fragment","rows":[]},{"id":"T39","mod":"poetyka","typ":"interpretacja","text":"Powieść Balzaka prawie zawsze daje przekrój społeczny od szczytów do nizin i pokazuje związki między faktami, których zwykle nie widzimy.","source":{"id":"S-BOY-BALZAK","quote":"Prawie zawsze daje on przekrój społeczny od szczytów do nizin","loc":"s. 108","seg":[[20,126,187]]},"status":"źródło","rows":[]},{"id":"T40","mod":"poetyka","typ":"interpretacja","text":"Paradoks mandaryna powraca w powieści jako motyw: Bianchon go odrzuca, a odpowiedź Rastignaca przy drugiej rozmowie przestaje być żartem.","refs":["P05","P06"],"source":{"id":"S-HZ2019","loc":"s. 10, 14"},"chars":["rastignac","bianchon"],"motif":["mandaryn"],"status":"źródło","rows":[]},{"id":"T41","mod":"poetyka","typ":"fakt","text":"Przypisanie paradoksu mandaryna Rousseau jest wątpliwe: takiego fragmentu nie znaleziono w jego dziełach, a za prawdopodobne źródło uchodzi „Geniusz chrześcijaństwa” Chateaubrianda.","source":{"id":"S-HZ2019","loc":"s. 10–13"},"motif":["mandaryn"],"status":"źródło","rows":[]},{"id":"T42","mod":"poetyka","typ":"interpretacja","text":"Bal pożegnalny pani de Beauséant i agonia Goriota tworzą kontrast: obowiązki towarzyskie córek wygrywają z ostatnią wolą ojca.","rows":[[2,0]],"links":[[2,19]],"chars":["goriot","anastazja","delfina","beauseant"],"status":"autorska","source":null},{"id":"T43","mod":"poetyka","typ":"interpretacja","text":"Dzieje Goriota i małżeństwa jego córek poznajemy z retrospekcji wstawionej w bieg akcji; przeszłość wyjaśnia teraźniejszą nędzę.","refs":["G03"],"chars":["goriot"],"status":"autorska","rows":[],"source":null}],"scenes":[{"id":"S01","title":"Opis pensjonatu","refs":["G01","P02"],"function":"Ekspozycja: wprowadza miejsce, które skupia wszystkie wątki, i ustala zasady opowiadania.","theses":["T33","T36","T38"],"questions":["Jakie cechy pensjonatu zapowiadają losy jego mieszkańców?","Po co narrator zwraca się bezpośrednio do czytelnika?"]},{"id":"S02","title":"Srebra Goriota","refs":["G08","G09"],"function":"Tajemnica: Rastignac widzi przez dziurkę od klucza czynność, której sensu jeszcze nie rozumie.","theses":["T37"],"questions":["Dlaczego scena jest pokazana z perspektywy Rastignaca, a nie narratora?","Co zniszczenie pamiątkowych sreber mówi o hierarchii wartości Goriota?"]},{"id":"S03","title":"Pierwsza wizyta u Restaudów","refs":["G10","G11"],"function":"Próba: pierwszy błąd Rastignaca w salonie ujawnia, czego wstydzą się córki Goriota.","theses":["T28"],"questions":["Jak jedno nazwisko zmienia przebieg wizyty?","Czego Rastignac dowiaduje się o świecie, w którym chce się znaleźć?"]},{"id":"S04","title":"Lekcja pani de Beauséant","refs":["G05","P13"],"function":"Inicjacja: arystokratka wykłada reguły świata, w którym powodzenie jest kluczem do władzy.","theses":["T15","T30"],"questions":["Na czym według pani de Beauséant polega powodzenie w Paryżu?","Jaką rolę w tej strategii odgrywają kobiety?"]},{"id":"S05","title":"Lekcja Vautrina","refs":["G28","G29","G30","P03","P04","P10"],"function":"Kontrapunkt: drugi mentor pokazuje ten sam świat bez złudzeń i proponuje drogę przez zbrodnię.","theses":["T05","T16","T31"],"questions":["Czym różni się diagnoza świata u Vautrina od lekcji pani de Beauséant, a w czym są zbieżne?","Jak Vautrin wycenia drogę uczciwej kariery?"]},{"id":"S06","title":"Listy do rodziny","refs":["G26","G27"],"function":"Koszt awansu: ofiara rodziny zostaje zestawiona z ofiarami Anastazji dla kochanka.","theses":["T16"],"questions":["Jakie argumenty Rastignac stosuje w prośbie o pieniądze?","Dlaczego porównuje siebie z Anastazją?"]},{"id":"S07","title":"Paradoks mandaryna","refs":["P05","P06"],"function":"Probierz sumienia: abstrakcyjne pytanie filozoficzne przybiera konkretną postać w planie Vautrina.","theses":["T40","T41","T32"],"questions":["Kogo w akcji powieści może oznaczać „mandaryn”?","Jak zmienia się sens żartu między pierwszą a drugą rozmową?"]},{"id":"S08","title":"Los Wiktoryny","refs":["P18","G07","G13","G14","G12"],"function":"Wątek poboczny ilustruje mechanizm dziedziczenia: śmierć brata zmienia ubogą sierotę w bogatą partię.","theses":["T08","T29"],"questions":["Co decyduje o wartości Wiktoryny jako kandydatki do małżeństwa?","Dlaczego jej los jest dla Rastignaca próbą moralną?"]},{"id":"S09","title":"Demaskacja Vautrina","refs":["G24","G25","G06"],"function":"Zwrot akcji: upadek najsilniejszej postaci pensjonatu następuje przez donos przeciętnych lokatorów.","theses":["T22"],"questions":["Dlaczego Vautrina pokonują Michonneau i Poiret, a nie siła?","Jak pensjonariusze oceniają donos panny Michonneau?"]},{"id":"S10","title":"Śmierć i pogrzeb Goriota","refs":["P08","P09","G37","G38","G39"],"function":"Kulminacja wątku ojcowskiego: pogrzeb opłacają obcy studenci, a córki przysyłają puste powozy.","theses":["T19","T20","T42"],"questions":["Jak Goriot w agonii ocenia swoje ojcostwo?","Co znaczą puste powozy z herbami w orszaku pogrzebowym?"]},{"id":"S11","title":"Wyzwanie rzucone Paryżowi","refs":["P11","G40"],"function":"Zakończenie otwarte: inicjacja się dopełnia, a bohater wraca do świata, który zabił Goriota.","theses":["T18","T09"],"questions":["Jak można rozumieć słowa „Teraz my się spróbujemy!”?","Dlaczego pierwszym krokiem Rastignaca jest obiad u pani de Nucingen?"]}],"contexts":[{"id":"C01","work":"Bolesław Prus, „Lalka”","theme":"pieniądz i pozycja","common":"Majątek nie wystarcza, by zostać przyjętym przez arystokrację; liczą się pochodzenie i salon.","diff":"Goriot oddaje pieniądze, by córki weszły wyżej, a sam zostaje wykluczony; Wokulski zdobywa majątek, by zbliżyć się do Izabeli, i przekonuje się, że arystokratyczny świat go nie przyjmie.","refs":["G03","G10"],"status":"autorska","source":null},{"id":"C02","work":"William Szekspir, „Król Lear”","theme":"ojcostwo i utrata władzy","common":"Ojciec za życia oddaje majątek córkom, a gdy nie ma już nic do dania, zostaje przez nie opuszczony.","diff":"Lear traci królestwo i władzę polityczną; Goriot jest mieszczaninem, a jego upadek przebiega w realiach finansowych i obyczajowych Paryża.","refs":["P09","P08","G39"],"status":"autorska","source":null},{"id":"C03","work":"Stendhal, „Czerwone i czarne”","theme":"awans","common":"Julien Sorel i Rastignac stanowią podstawy literackiego typu karierowicza, który otrzyma nazwę dopiero w 1893 roku.","diff":"Sorel wywodzi się z niższej warstwy i nie zostaje przyjęty z powodu pochodzenia; Rastignac pochodzi ze zubożałej szlachty i korzysta z koneksji rodzinnych.","refs":["G04","G40"],"source":{"id":"S-HZ2019","loc":"s. 16–17; por. S-HZ2018, s. 106"},"status":"źródło"},{"id":"C04","work":"Fiodor Dostojewski, „Zbrodnia i kara”","theme":"moralny koszt korzyści","common":"Pytanie, czy wolno poświęcić cudze życie dla dobra własnego lub bliskich, pada w rozmowie młodych ludzi: Rastignaca z Bianchonem oraz studenta z oficerem, którą podsłuchuje Raskolnikow.","diff":"Rastignac nie zabija i odrzuca plan Vautrina, choć z niego korzysta; Raskolnikow sam popełnia zbrodnię i ponosi jej konsekwencje.","refs":["P05","P06","G31"],"status":"autorska","source":null}],"czz":{"title":"„Komedja ludzka” na tle epoki","source":"S-BOY-BALZAK","from":"Panowanie Ludwika Filipa","to":"pozował mu do jego dzieła, poczynając od owej księżnej de Castries, która posłużyła mu za model do niejednej arystokratycznej damy.","questions":["Jakie dwie cechy panowania Ludwika Filipa autor nazywa cnotami, które dopiero „dziś umiemy ocenić”?","Wyjaśnij, dlaczego Boy nazywa Balzaka „poetą pieniądza”.","Czym według autora różni się ujęcie pieniądza u Balzaka od jego obecności w komediach Moliera?","Jak autor określa Goriota w wyliczeniu postaci „Komedii ludzkiej”?","Co autor rozumie przez „prawo mimicry”? Podaj przykład z „Ojca Goriot”.","Jak autor odróżnia metodę Balzaka od „zwykłej obserwacji realisty”?"],"key":["Pokój za wszelką cenę oraz popieranie przemysłu i handlu.","Bo pieniądz jest u niego przemożną, niemal symboliczną siłą, która przenika wszystko i kształtuje sprawy wielkie i drobne; Balzac ukazuje go dokładnie, aż do stanu posiadania bohaterów.","U Moliera pieniądz był abstrakcją, „złotem”; u Balzaka jest pokazany realistycznie: jak powstaje i krąży, kto go zdobywa i wydaje.","„Ex-jakobin Goriot, spekulujący niegdyś na żywności” — jeden z dwóch starych „poczciwców”.","Upodabnianie się żywej osoby do tła; np. pani Vauquer i jej pensjonat opisane tak, że wygląd gospodyni i domu nawzajem się tłumaczą (przykład należy uzasadnić tekstem).","To nie jest zwykła obserwacja, lecz „intuicja poety”; Balzac nie portretował osób z rzeczywistości, tylko tworzył postacie syntetycznie."],"paras":[{"page":99,"text":"Panowanie Ludwika Filipa, króla którego usymbolizowano jako jegomościa z parasolem, dlatego że lubił się tak po mieszczańsku przechadzać po Paryżu, stał się tryumfem mieszczaństwa. Pokój za wszelką cenę, popieranie przemysłu i handlu, to są cnoty które dziś umiemy ocenić, ale wówczas budziły one pogardę dla tego króla-filistra. Miejsce dawnej armji Napoleona zajęła gwardja narodowa, której oficer, — jakiś zbogacony kupiec — z trudem dopinał mundur na wypukłym brzuszku. Przekupstwo korygowało szeroką ustawę wyborczą. Fortuny mieszczańskie rosły, pieniądz coraz bardziej niwelował różnice społeczne, wymieszanie warstw postępowało dalej. To panowanie, niesympatyczne Balzakowi, trwało osiemnaście lat i znalazło również gwałtowny koniec. Bo już, poza sytem mieszczaństwem, dojrzewała nowa potęga, której nie umiano docenić: uświadomiony robotnik. Daremnie różni ideolodzy jak Saint-Simon, jak Fourier i inni silili się znaleźć rozwiązanie kwestji ekonomicznej: w roku 1848 „kwestja“ ta wyszła na ulicę i wzniosła barykady.","brk":[]},{"page":99,"text":"Balzac stał się tedy historjografem owych kolejnych epok. Ten sam powieściopisarz, który odgadł wszystkie sekrety kobiecego serca, przejrzał i tajemnicę mechanizmu społecznego. Różne odcienie myśli społecznej, wszelkie warstwy, grupy, ewolucje idej i interesów, wszystko to daje bogate tło poszczególnym jego powieściom. Psychologja przeżytków napoleońskich w epoce trwałego pokoju, wyrastanie olbrzymich fortun ponad miarę małych ludzi których stały się udziałem, niemoralna potęga prasy i giełdy, zmieniające się obyczaje handlowe, kombinacje finansowo-małżeńskie, szarlatanerje polityczne, twórcza gorączka wynalazcy wraz z nieodłącznym spekulantem który go wyzyskuje, walka bezrolnych z wielką własnością, mieszczaństwa ze szlachtą, zamki prowincjonalne i sutereny paryskie, wszystko to pokazuje nam kolejno lub naraz. I jak to wszystko żyje, jak mocno wiąże się z sobą!","brk":[[83,100]]},{"page":100,"text":"Balzac staje się tedy poetą pieniądza: możnaby powiedzieć, że to on go wymyślił, stworzył. Balzac widzi w nim to, czem jest w istocie w życiu; czem stał się zwłaszcza w jego społeczeństwie; przemożną, symboliczną niemal siłę, fluid przenikający wszystko, wciskający się wszędzie, czynnik kształtujący największe i najdrobniejsze sprawy, niezbędny do zrozumienia życia i ludzi. Stąd ta drobiazgowa troska, z jaką notuje co do centyma stan posiadania swoich bohaterów; stąd ten zawrotny taniec miljonów, stanowiący konkluzję każdej niemal jego powieści. Pieniądz jest dla Balzaka nicią Arjadny, która prowadzi go nieomylnie w labiryncie nowego społeczeństwa; daje mu wyczuć związki między pałacem a sutereną, Paryżem a prowincją, tworami ducha a przyziemnością materji. Pieniądz jako motyw artystyczny, to jeden z tysiąca szczegółów, dziś już tak spospolitowanych iż wogóle nie przychodzi na myśl że ktoś pierwszy je zaobserwował, a będących niepodzielną prawie zdobyczą Balzaka.","brk":[[370,101]]},{"page":101,"text":"Nie znaczy to, aby pieniądz nie odgrywał roli w dawnej literaturze. W iluż komedjach Moljera wszystko kręci się koło niego! Ale dotąd był on abstrakcją, — „złotem“. Tu mamy pieniądz w całym drobiazgowym realizmie jego materjału, jego powstawania, krążenia. Pieniądz bankiera, lichwiarza, rolnika, aferzysty, kupca, — tysiąc sposobów zdobywania go, tysiąc sposobów wydawania. Pieniądz, to Nucingen i Rastignac, i Gobseck, i pan de La Baudraye i stary Grandet...","brk":[]},{"page":101,"text":"Ile stanów, ile odcieni! Dwaj starzy „poczciwcy“: ex-jakobin Goriot, spekulujący niegdyś na żywności, i wierny rojalista Ragon, właściciel handlu perfumami; następca Ragona, Birotteau, ginący typ skromnego jeszcze mieszczaństwa wzrosłego w dawnych tradycjach, i następca Cezara Birotteau, parwenjusz Crevel (Kuzynka Bietka), symbol nadętego i tryumfującego mieszczaństwa z epoki Ludwika Filipa. Armia Napoleona, od bohaterów do szumowin (Kawalerskie gospodarstwo), a jak mistrzowsko narysowane przejścia od jednych do drugich! Toż samo wszystkie profesje, zawody, stany: artyści, finanse, polityka, arystokracja. Do dziś — mimo iż Zola w swoich Rougon-Macquart podjął niejako unowocześnienie dzieła Balzaka, mimo iż na swój sposób natchnęli się duchem Balzaka Galsworthy w swoich Forsytach, Proust, Jules Romains wreszcie w Ludziach dobrej woli — niema lepszego niż Balzac przewodnika w wielkiej dżungli życia!","brk":[[81,102]]},{"page":102,"text":"Toż samo przemysł, rolnictwo, polityka, sztuka. Ten człowiek o wzroku czarownika widzi w każdym najdrobniejszym fakcie nieskończone perspektywy uogólnień, zależności. Widzi związki pomiędzy upadkiem Napoleona a przesileniem w szmuklerstwie; między szczęśliwą miłością a wzrostem rachunku praczki. Nic go nie omami, nie gardzi żadnym płaskim napozór szczegółem.","brk":[[288,103]]},{"page":103,"text":"Tak jak w pierwszym swoim utworze, Szuanach, wprowadził Balzac w powieść topografję, tak i całą Komedję ludzką uczyni żywą geografją Francji. Nie mówiąc o Paryżu, z którego stworzy cały poemat, każde z jego opowiadań, rozgrywających się na prowincji, aż pachnie prawdą lokalną. Każdą podróż, każde wytchnienie, wyzyskuje Balzac na to, aby utrwalać w mózgu obrazy, które będą tłem jego powieści. Jeździ, notuje, wywiaduje się, gwarzy z ludźmi, pyta o ceny wszystkiego. Posiada sztukę odcyfrowywania życia przedmiotów. Bo to nie jest zwykła obserwacja realisty, — to intuicja poety.","brk":[]},{"page":103,"text":"Jak żywo oddana jest naprzykład w Dwóch poetach psychologia wyżniego i niżniego miasta Angoulême; ileż koloru zyskuje pod jego piórem opis La Grenadière koło Tours, albo czar brzegów Loary i Charente! Balzac był może pierwszy, który „nadał kurs“ urodzie Francji, przeciwstawiając ją owej Italji, która w epoce romantyzmu posiadała, obok Szwajcarji, monopol na piękności przyrody. Każda powieść Balzaka znajduje dla siebie ramę w jakiemś jego wspomnieniu: ta lub inna miejscowość we Francji, — dom lub ulica, jeżeli chodzi o Paryż, — opisane są jakże sugestywnie, współżyją wręcz z bohaterami. Balzac odgadł prawo mimicry, upodobnianie się żywej osoby do tła. Aby stwierdzić, do jakiego stopnia ta geografja literacka była wynalazkiem Balzaka, wystarczy porównać jego utwory z jakąkolwiek powieścią przedbalzakowską. Weźmy naprzykład Adolfa, którego akcja toczy się kolejno w Niemczech, w Czechach, w Polsce, bez śladu jakiegokolwiek kolorytu lokalnego. Troskę swoją o prawdę posuwał Balzac tak daleko, że dobór nazwisk jego bohaterów był dlań przedmiotem długich refleksyj i poszukiwań. Czasem na szyldzie jakiegoś sklepu znajdował nazwisko, na które długo bezskutecznie polował (Z. Marcas).","brk":[[442,104]]},{"page":104,"text":"Mimo że nigdy prawie nie portretował z rzeczywistości, ale zawsze tworzył figury swoje syntetycznie, każdy prawie znajomy mimowoli pozował mu do jego dzieła, poczynając od owej księżnej de Castries, która posłużyła mu za model do niejednej arystokratycznej damy.","brk":[]}],"pages":[99,104]},"passages":[{"id":"P01","title":"Paryż jako ocean","bort":{"text":["Ale Paryż to istny ocean. Na próżno sondę zapuszczać będziecie, nigdy nie zbadacie jego głębokości."],"seg":[[15,1637,1736]],"page":6,"pages":[6]},"boy":{"text":["Ale Paryż to prawdziwy ocean. Możecie rzucać weń sondę, nigdy nie poznacie prawdziwej jego głębokości."],"seg":[[11,1447,1549]],"page":26,"pages":[26]}},{"id":"P02","title":"„All is true”","bort":{"text":["Ach! wierzcie mi, ten dramat nie jest ani wymysłem, ani romansem. All is true, jest on tak prawdziwy, że każdy znajdzie w sobie, może nawet w swym sercu, te same czynniki, z których on się składa."],"seg":[[1,1643,1839]],"page":2,"pages":[2]},"boy":{"text":["Ach, wiedzcie: dramat ten nie jest ani wymysłem, ani romansem. All is true, jest on tak prawdziwy, że każdy odnajdzie jego składniki w sobie, może we własnym sercu."],"seg":[[0,2175,2339]],"page":18,"pages":[18]}},{"id":"P03","title":"Vautrin: nie ma zasad","bort":{"text":["Nie ma na świecie zasad, są tylko wypadki, nie ma praw, są tylko okoliczności. Człowiek wyższy umie korzystać z trafu i z okoliczności."],"seg":[[557,1750,1885]],"page":51,"pages":[51]},"boy":{"text":["Nie ma zasad, są tylko wypadki; nie ma praw, tylko okoliczności: człowiek wyższy chwyta w ręce wypadki i okoliczności, aby nimi kierować."],"seg":[[569,1469,1606]],"page":115,"pages":[115]}},{"id":"P04","title":"Vautrin o hipokryzji społecznej","bort":{"text":["Inny ukradł milion i uchodzi w salonach za wzór cnoty."],"seg":[[188,320,374]],"page":22,"pages":[22]},"boy":{"text":["Ukradnij milion, będziesz figurował w salonach jako cnota."],"seg":[[190,239,297]],"page":56,"pages":[56]}},{"id":"P05","title":"Paradoks mandaryna","bort":{"text":["— Czy przypominasz sobie ten ustęp, gdzie autor zapytuje, co by czytelnik zrobił, gdyby mógł, nie ruszając się z Paryża, siłą woli tylko zabić jakiegoś mandaryna w Chinach?","— Przypominam.","— I cóż ty na to?","— Zachciałeś! Ja myślę już o trzydziestym trzecim mandarynie.","— Nie żartuj. Słuchaj, gdybyś wiedział, że to rzecz prawdopodobna, że chodzi tylko o twe skinienie, powiedz, jakbyś postąpił?","— A czy ten mandaryn bardzo stary? Wreszcie, młody czy stary, sparaliżowany czy zdrów, co mi tam! Słowo daję, że… Do licha! Nie, ja bym się nie zgodził."],"seg":[[694,0,172],[695,0,14],[696,0,17],[697,0,61],[698,0,125],[699,0,152]],"page":61,"pages":[61]},"boy":{"text":["— Przypominasz sobie ustęp, w którym pyta czytelnika, co by uczynił, gdyby mógł się stać bogatym, zabijając w Chinach, jedynie mocą swojej woli, nie ruszając się z Paryża, starego mandaryna?","— Tak.","— No i...?","— Ba! jestem właśnie przy trzydziestym trzecim mandarynie.","— Nie żartuj. No więc, gdyby ci udowodniono, że rzecz jest możliwa i że wystarczy skinienie głową, zrobiłbyś...?","— A stary ten mandaryn? Ale ba! młody czy stary, sparaliżowany czy zdrów jak ryba, na honor... Do paralusza! Otóż — nie."],"seg":[[709,0,190],[710,0,6],[711,0,10],[712,0,58],[713,0,112],[714,0,120]],"page":135,"pages":[135,136]}},{"id":"P06","title":"Powrót mandaryna","bort":{"text":["— Czy nie zabiliśmy tylko mandaryna? — zapytał go raz Bianchon, wstając od stołu.","— Nie umarł dotychczas, ale już charczy — odparł Eugeniusz.","Student medycyny wziął te słowa za żart, ale Eugeniusz nie myślał żartować."],"seg":[[819,0,81],[820,0,59],[821,0,75]],"page":70,"pages":[70]},"boy":{"text":["— Zabiliśmy tedy mandaryna? rzekł doń pewnego dnia Bianchon, wstając od stołu.","— Jeszcze nie, odparł, ale rzęzi.","Student wziął to za żart, a nie było to żartem!"],"seg":[[834,0,78],[835,0,33],[836,0,47]],"page":152,"pages":[152]}},{"id":"P07","title":"Ideał ojcostwa / Chrystus ojcostwa","bort":{"text":["Chcąc dobrze odmalować oblicze tego ideału ojcostwa, trzeba by szukać wzoru w postaciach, które mistrze pędzla stworzyli dla oddania męki Zbawiciela, cierpiącego za świat cały."],"seg":[[1286,110,286]],"page":96,"pages":[96]},"boy":{"text":["Aby dobrze oddać twarz tego Chrystusa ojcostwa, trzebaby szukać porównań w obrazach, które wymyślili mistrze pędzla, aby odmalować mękę ścierpianą przez Zbawiciela dla dobra świata."],"seg":[[1287,38,219]],"page":205,"pages":[205]}},{"id":"P08","title":"Świat stoi na ojcostwie","bort":{"text":["Społeczeństwo, świat cały stoi na ojcostwie, wszystko więc runie, gdy dzieci nie będą ojców kochały."],"seg":[[1671,4556,4656]],"page":120,"pages":[120]},"boy":{"text":["Społeczeństwo, świat wspierają się na ojcostwie, wszystko zawali się, jeśli dzieci nie będą kochały rodziców."],"seg":[[1660,3946,4055]],"page":251,"pages":[251]}},{"id":"P09","title":"Pieniądz daje wszystko","bort":{"text":["Tak, mógłbym mieć to wszystko, a nic nie mam, pieniądz daje wszystko, nawet córki."],"seg":[[1671,302,384]],"page":119,"pages":[119]},"boy":{"text":["Miał bym to wszystko. Ale nic!... Pieniądz daje wszystko, nawet dzieci."],"seg":[[1660,234,305]],"page":250,"pages":[250]}},{"id":"P10","title":"Rachunek Vautrina: koszt życia w Paryżu","bort":{"text":["Cóż, synku, musimy mieć dwadzieścia pięć tysiączków rocznie, lub wpadamy w błoto, wystawiamy się na pośmiewisko i jesteśmy pozbawieni przyszłości, powodzenia, kochanek!"],"seg":[[815,1588,1756]],"page":69,"pages":[69]},"boy":{"text":["Razem, piękne dziecię, doliczyli byśmy się dwudziestu pięciu tysięcy na rok, inaczej wleziemy w błoto, ściągniemy na siebie drwiny i możemy pożegnać przyszłość, powodzenie, kochanki!"],"seg":[[832,1340,1522]],"page":150,"pages":[150]}},{"id":"P11","title":"Widok Paryża z Père-Lachaise","bort":{"text":["Oczy studenta zatrzymały się chciwie pomiędzy kolumną placu Vendôme a kopułą Inwalidów, w miejscu, gdzie żyło towarzystwo wykwintne, do którego on dostać się usiłował. Zmierzył ten ul brzęczący spojrzeniem, które zdawało się od razu wszystek miód z niego wysysać, i wyrzekł te wielkie słowa:"],"seg":[[1809,161,452]],"page":128,"pages":[128]},"boy":{"text":["Oczy jego uczepiły się niemal chciwie miejsca między placem Vendôme a kopułą Inwalidów, miejsca gdzie żył ten wykwintny świat, do którego chciał się dostać. Objął ten brzęczący ul spojrzeniem, które wysysało zeń zawczasu wszystkie miody, i wyrzekł te dumne słowa:"],"seg":[[1796,157,420]],"page":267,"pages":[267]}},{"id":"P12","title":"Łowca milionów","bort":{"text":["pan jesteś łowiec milionów. Chcesz je pan schwytać, więc robisz zasadzki, zastawiasz sieci, nęcisz na wabika."],"seg":[[549,1615,1724]],"page":50,"pages":[50]},"boy":{"text":["ty jesteś łowcą milionów. Aby je chwycić, używasz podstępów, zasadzek, przynęt."],"seg":[[561,1452,1531]],"page":113,"pages":[113]}},{"id":"P13","title":"Dwa domy, dwie dzielnice","bort":{"text":["mógł bywać na przedmieściu Saint-Germain u wicehrabiny de Beauséant, a na Chaussée-d’Antin uklęknąć przed hrabiną de Restaud;"],"seg":[[62,1342,1467]],"page":16,"pages":[16]},"boy":{"text":["oprzeć stopę w Saint-Germain u wicehrabiny de Beauséant, kolano na Chaussée d’Antin u hrabiny de Restaud!"],"seg":[[62,1193,1298]],"page":45,"pages":[45]}},{"id":"P14","title":"Rok 1819","bort":{"text":["Jednakże w roku 1819, to jest w chwili rozpoczęcia się naszego dramatu, mieszkała tam jedna uboga dziewczyna."],"seg":[[0,599,708]],"page":2,"pages":[2]},"boy":{"text":["W 1819 r. wszakże, epoce w której rozpoczyna się ten dramat, zamieszkała tam jedna młoda panienka."],"seg":[[0,542,640]],"page":17,"pages":[17]}},{"id":"P15","title":"Goriot u pani Vauquer od 1813 roku","bort":{"text":["Ojciec Goriot, starzec prawie sześćdziesięciodziewięcioletni, przeprowadził się do pani Vauquer w 1813 roku, wycofawszy się poprzednio z interesów."],"seg":[[22,0,147]],"page":9,"pages":[9]},"boy":{"text":["Ojciec Goriot, starzec sześćdziesięciodziewięcioletni, osiedlił się u pani Vauquer w 1813, wycofawszy się z interesów."],"seg":[[17,0,118]],"page":30,"pages":[30]}},{"id":"P16","title":"Luty 1820: termin wyprowadzki","bort":{"text":["— Proszę pana — rzekła wdowa — i ojciec Goriot i pan mieliście opuścić mój dom piętnastego lutego. Tymczasem trzy dni upłynęły już od tej daty."],"seg":[[1520,0,143]],"page":110,"pages":[110]},"boy":{"text":["— Proszę pana, rzekła wdowa, pan Goriot i pan mieliście się wyprowadzić 15 lutego. Oto już trzy dni jak 15 minął, mamy dziś 18;"],"seg":[[1513,0,127]],"page":232,"pages":[232]}},{"id":"P17","title":"Data pod tekstem","bort":{"text":["Sache, we wrześniu 1834."],"seg":[[1811,81,105]],"page":128,"pages":[128]},"boy":{"text":["Saché, wrzesień 1834."],"seg":[[1799,0,21]],"page":267,"pages":[267]}},{"id":"P19","title":"Grudniowe listy z domu","bort":{"text":["W pierwszych dniach grudnia Rastignac otrzymał dwa listy: od matki i od starszej siostry."],"seg":[[493,0,89]],"page":41,"pages":[41]},"boy":{"text":["Z początkiem grudnia Rastignac otrzymał dwa listy, jeden od matki, drugi od starszej siostry."],"seg":[[501,0,93]],"page":96,"pages":[96]}},{"id":"P18","title":"Wydziedziczenie Wiktoryny","bort":{"text":["Ojciec Wiktoryny sądził się w prawie nie uznawać córki, nie chciał jej mieć przy sobie, przeznaczał jej tylko sześćset franków rocznie, wreszcie sprzedał swoje dobra, chcąc wszystko przekazać synowi."],"seg":[[16,1457,1656]],"page":7,"pages":[7]},"boy":{"text":["Ojciec Wiktoryny, podejrzewając że to dziecko nie jest jego, nie chciał jej przy sobie, wyznaczył córce jedynie sześćset franków rocznie i obszedł prawo, aby przekazać cały majątek synowi."],"seg":[[12,1162,1350]],"page":27,"pages":[27]}}],"variants":{"G01":{"text":["Pani Vauquer, z domu Conflans, jest to starsza dama, która od czterdziestu lat prowadzi w Paryżu gospodę przy ulicy Neuve-Sainte-Geneviève, między Dzielnicą Łacińską a przedmieściem St. Marcel."],"seg":[[0,0,193]],"page":17,"pages":[17]},"G02":{"text":["postanowił zebrać testy drugiego i trzeciego roku, aby przestudiować gruntownie całe prawo naraz, w ostatniej chwili. Miał w ten sposób pięć kwartałów swobody, aby żeglować po oceanie Paryża, aby frymarczyć względami kobiet lub łowić w nim fortunę."],"seg":[[494,466,714]],"page":92,"pages":[92]},"G03":{"text":["Anastazja, która pięknością swoją zawróciła głowę hrabiemu de Restaud, miała popędy arystokratyczne; opuściła dom rodzinny, aby wejść w wysokie sfery. Delfina lubiła pieniądze: zaślubiła Nucingena, bankiera niemieckiego pochodzenia, świeżo upieczonego barona Stolicy Apostolskiej."],"seg":[[499,811,1091]],"page":95,"pages":[95]},"G04":{"text":["Przetrząsnąwszy gałęzie drzewa genealogicznego, stara dama osądziła, iż, w samolubnym plemieniu bogatych krewnych, ze wszystkich osób, które mogłyby podać rękę siostrzeńcowi, wicehrabina de Beauséant będzie może najprzystępniejsza. Napisała do tej młodej kobiety list w staroświeckim stylu i powierzyła go Eugeniuszowi, powiadając, iż, w razie powodzenia, wicehrabina wprowadzi go do innych domów."],"seg":[[56,1224,1621]],"page":43,"pages":[43]},"G05":{"text":["Będziesz miał powodzenie. W Paryżu powodzenie jest wszystkim, to klucz do władzy. Jeżeli kobiety znajdą w tobie dowcip, talenty, mężczyźni uwierzą w to, o ile ich nie wywiedziesz z błędu. Posiądziesz wówczas wszystko czego zapragniesz, będziesz u siebie wszędzie."],"seg":[[455,2712,2975]],"page":87,"pages":[87]},"G06":{"text":["— Przyznaję, że jestem Jakub Collin, zwany Ołży-Śmierć, skazany na dwadzieścia lat kajdanów;"],"seg":[[1154,129,221]],"page":192,"pages":[192]},"G07":{"text":["Pani Couture, daleka krewna matki, która niegdyś schroniła się u niej aby umrzeć z rozpaczy, zaopiekowała się sierotą jak własnym dzieckiem."],"seg":[[12,1351,1491]],"page":27,"pages":[27]},"G08":{"text":["Ojciec Goriot przymocował do listwy przewróconego stołu srebrny półmisek i wazkę, wziął sznur i okręcił go dokoła tych bogato rzeźbionych przedmiotów, ściskając z taką siłą, jak gdyby chciał je zmienić w bryłę litego metalu."],"seg":[[62,2426,2650]],"page":45,"pages":[45,46]},"G09":{"text":["Sprzedał mu za ładną sumę srebrny serwis, wcale grzecznie ugnieciony, jak na kogo kto nie należy do cechu."],"seg":[[119,107,213]],"page":50,"pages":[50]},"G10":{"text":["Na to nazwisko, ozdobione wyrazem ojciec, hrabia, który grzebał w piecu, rzucił szczypce w ogień, jak gdyby go sparzyły w palce i wstał.","— Można by powiedzieć pan Goriot! — wykrzyknął."],"seg":[[319,0,136],[320,0,47]],"page":70,"pages":[70]},"G11":{"text":["Wymówione przez Eugeniusza nazwisko było niby dotknięcie różdżki czarodziejskiej, ale o działaniu wręcz przeciwnym temu, jakie wywarły słowa: Krewny pani de Beauséant."],"seg":[[330,0,167]],"page":70,"pages":[70]},"G12":{"text":["— Wiktoryna?","— Właśnie!","— I jak?","— Już kocha się w tobie młoda baronowa de Rastignac!","— Toż ona nie ma ani grosza, rzekł Eugeniusz zdumiony."],"seg":[[564,0,12],[565,0,10],[566,0,8],[567,0,52],[568,0,54]],"page":114,"pages":[114]},"G13":{"text":["Podczas gdy będziemy słodko drzemać, pułkownik hrabia Franchessini otworzy ci sukcesję po Michale Taillefer ostrzem szpady. Dziedzicząc po bracie, Wiktoryna będzie miała swoich piętnaście tysiączków renty."],"seg":[[1008,511,716]],"page":175,"pages":[175]},"G14":{"text":["Młody Taillefer bił się z hrabią Franchessini, ze starej gwardii, który mu wpakował szpadę na dwa cale w czoło. I oto nasza Wiktoryna jest jedną z najbogatszych partii w Paryżu. Hej! gdyby to był człowiek przewidział."],"seg":[[1127,37,254]],"page":188,"pages":[188]},"G15":{"text":["przyłożyłem mu synapizmy; na szczęście czuje je, działają.","— Czy można go przenieść?","— Niepodobna. Trzeba go zostawić gdzie jest, strzec go od wszelkiego ruchu, wzruszenia.","— Mój poczciwy Horacy, rzekł Eugeniusz, będziemy go pielęgnowali we dwóch.","— Wezwałem już naczelnego lekarza ze szpitala."],"seg":[[1525,63,121],[1526,0,25],[1527,0,87],[1528,0,74],[1529,0,46]],"page":233,"pages":[233]},"G16":{"text":["Następnie, spędzili noc czuwając kolejno przy chorym, przy czym Bianchon czytał medyczne książki, Rastignac zaś pisał do matki i sióstr."],"seg":[[1545,51,187]],"page":235,"pages":[235]},"G17":{"text":["Pani Vauquer podziwiała osiemnaście koszul z holenderskiego płótna, których cienkość biła w oczy tym bardziej, iż fabrykant makaronu wpinał w żabot duże diamentowe szpilki połączone złotym łańcuszkiem."],"seg":[[17,797,998]],"page":31,"pages":[31]},"G18":{"text":["Na nieszczęście, z końcem drugiego roku, pan Goriot usprawiedliwił gadania których był przedmiotem, prosząc panią Vauquer o przeniesienie go na drugie piętro i o zniżenie pensji do dziewięciuset franków. Stary rozwinął tak ścisłą oszczędność, że nigdy nie paliło się u niego w zimie. Pani Vauquer zażądała zapłaty z góry, w czem pan Goriot, którego odtąd nazywała ojcem Goriot, nie stawiał trudności."],"seg":[[34,1276,1676]],"page":36,"pages":[36]},"G19":{"text":["Pod koniec trzeciego roku, ojciec Goriot jeszcze ograniczył wydatki, przenosząc się na trzecie piętro i obniżając pensję do czterdziestu pięciu franków na miesiąc. Poniechał tabaki, oddalił fryzjera i przestał używać pudru."],"seg":[[48,0,223]],"page":39,"pages":[39]},"G20":{"text":["przypominasz sobie niedawno ów weksel Maksyma? To nie był pierwszy. Zapłaciłam już takich wiele. W początkach stycznia pan de Trailles wydawał się bardzo stroskany."],"seg":[[1388,75,239]],"page":220,"pages":[220]},"G21":{"text":["Sprzedaż diamentów nie dała stu tysięcy. Maksyma ścigają. Trzeba nam spłacić jeszcze tylko dwanaście tysięcy franków. Przyrzekł mi że będzie rozsądny, przestanie grać. Została mi na świecie już tylko jego miłość: za drogo ją opłaciłam, umarłabym gdybym ją miała stracić."],"seg":[[1409,81,351]],"page":223,"pages":[223]},"G22":{"text":["Ponieważ wziął mój posag, zapłacił; ale wyznaczył mi od tego czasu pensję, na którą się zgodziłam, aby mieć spokój. Później chciałam uczynić zadość miłości własnej kogoś kogo pan zna, rzekła."],"seg":[[795,1409,1600]],"page":144,"pages":[144]},"G23":{"text":["Rzucił wszystkie swoje i moje kapitały w ledwo rozpoczęte przedsiębiorstwa, w które trzeba było włożyć wielkie sumy."],"seg":[[1361,66,182]],"page":215,"pages":[215]},"G24":{"text":["Gdy Sylwia i służący opuścili jadalnię, panna Michonneau, która zeszła pierwsza, wlała płyn do srebrnego kubka Vautrina, w którym to kubku śmietanka do kawy grzała się w gorącej kąpieli."],"seg":[[1063,560,746]],"page":183,"pages":[183]},"G25":{"text":["Skoro Vautrina odwrócono, panna Michonneau zaaplikowała mu na bark silnego klapsa; dwie nieszczęsne litery zajaśniały biało w zaczerwienionym miejscu."],"seg":[[1108,0,150]],"page":186,"pages":[186]},"G26":{"text":["Jeżeli, dla zaokrąglenia sumy, niema innego sposobu jak tylko sprzedać ciotczyne koronki, powiedz że kupię jej ładniejsze”, etc.","Napisał do sióstr, prosząc aby mu przesłały swoje oszczędności;"],"seg":[[487,1394,1522],[488,0,63]],"page":91,"pages":[91]},"G27":{"text":["— Matka pozbyła się klejnotów! powiadał sobie. Ciotka płakała z pewnością, sprzedając swoje relikwie! Jakim prawem miałbyś przeklinać Anastazję?"],"seg":[[505,0,144]],"page":98,"pages":[98]},"G28":{"text":["Jeśli nie będziesz miał protekcji, zgnijesz na prowincji."],"seg":[[559,2785,2842]],"page":108,"pages":[108]},"G29":{"text":["Miej protekcje, będziesz prokuratorem w trzydziestym roku z tysiącem talarów płacy i ożenisz się z córką mera."],"seg":[[559,3086,3196]],"page":108,"pages":[108,109]},"G30":{"text":["W dwóch słowach, jeśli ci dostarczę posagu w wysokości miliona, czy dasz mi dwieście tysięcy franków? Dwadzieścia od sta prowizji, hę? Czy to nie za drogo? Rozkochasz w sobie młodą żonkę."],"seg":[[559,10672,10859]],"page":112,"pages":[112]},"G31":{"text":["Uczynił poniekąd rachunek sumienia. Jeśli pasował się z sobą, zgłębiał się, wahał, bądź co bądź uczciwość jego wyszła z tej twardej i straszliwej dyskusji niby sztaba żelaza, która oprze się wszystkim próbom."],"seg":[[1134,62,270]],"page":188,"pages":[188]},"G32":{"text":["Jadł prawie co dzień obiad u pani de Nucingen, której towarzyszył w świecie. Wracał o trzeciej lub czwartej rano, wstawał w południe aby się ubrać, jechał z Delfiną do lasku kiedy było ładnie,"],"seg":[[833,218,410]],"page":151,"pages":[151]},"G33":{"text":["I, jako pierwszy akt wyzwania które rzucił społeczeństwu, Rastignac poszedł na obiad do pani de Nucingen."],"seg":[[1798,0,105]],"page":267,"pages":[267]},"G34":{"text":["Młodzi studenci medycyny, widząc jego obwisłą dolną wargę i zmierzywszy kąt twarzowy, orzekli po bezskutecznych próbach wydobycia zeń czegoś, że to po prostu kretyn."],"seg":[[49,1142,1307]],"page":40,"pages":[40]},"G35":{"text":["Pani Vauquer zażądała zapłaty z góry, w czem pan Goriot, którego odtąd nazywała ojcem Goriot, nie stawiał trudności. Zaczęto na wyprzódki zgadywać przyczyny tego, ale dochodzenie było trudne! Jak orzekła fałszywa hrabina, ojciec Goriot był to człowiek skryty, mruk."],"seg":[[34,1560,1825]],"page":36,"pages":[36]},"G36":{"text":["Na to nazwisko, ozdobione wyrazem ojciec, hrabia, który grzebał w piecu, rzucił szczypce w ogień, jak gdyby go sparzyły w palce"],"seg":[[319,0,127]],"page":70,"pages":[70]},"G37":{"text":["Skoro Eugeniusz i Bianchon ukończyli jedzenie, szczęk widelców i łyżek, śmiechy obecnych, rozmaite wyrazy łakomych i obojętnych twarzy, wszystko to ścięło ich grozą. Wyszli, aby poszukać księdza, któryby czuwał i modlił się w nocy przy zwłokach. Trzeba im było dostroić ostatnie posługi koło nieboszczyka do skromnego stanu kasy którą rozporządzali."],"seg":[[1781,158,507]],"page":264,"pages":[264]},"G38":{"text":["Student medycyny podjął się tedy sam włożyć trupa do trumny dla ubogich, którą kazał przynieść ze szpitala, uzyskawszy opust.","— Wypłataj figla tym hultajom, rzekł do Eugeniusza."],"seg":[[1781,1406,1531],[1782,0,51]],"page":265,"pages":[265]},"G39":{"text":["Jednakże, w chwili gdy umieszczono trumnę na karawanie, dwie karety, zdobne herbami ale próżne, jedna hrabiego de Restaud, druga barona de Nucingen, przyłączyły się i odprowadziły kondukt aż na cmentarz."],"seg":[[1795,0,203]],"page":267,"pages":[267]},"G40":{"text":["— Teraz się spróbujemy!","I, jako pierwszy akt wyzwania które rzucił społeczeństwu, Rastignac poszedł na obiad do pani de Nucingen."],"seg":[[1797,0,23],[1798,0,105]],"page":267,"pages":[267]}}};
